def log_lerp(x, a, b):
  return a * jnp.exp(jnp.log(b/a) * x)

def learning_rate_decay(
    step, lr_init, lr_final, max_steps, lr_delay_steps=0, lr_delay_mult=1
):

  if step < lr_delay_steps:
    delay_rate = 0.5 * (1 + jnp.cos(jnp.pi * (step / lr_delay_steps)))
    delay_rate = lr_init * lr_delay_mult * delay_rate
  else:
    delay_rate = 1.0

  fraction = step / max_steps
  interpolated_lr = log_lerp(fraction, lr_init, lr_final)
  adjusted_lr = delay_rate * interpolated_lr

  return adjusted_lr
